insert into public.sentences (text, text_zh, notebook_id) values ('You are only secure if you can lose your fortune without the additional worse insult of having to become humble.', '只有在你能失去财富而不再遭受更糟的屈辱——被迫变得谦卑时，你才算安全。', 34);
insert into public.sentences (text, text_zh, notebook_id) values ('To test someone''s robustness to reputational errors, ask a man in front of an audience if he is "still doing poorly" or if he is "still losing money" and watch his reaction.', '要测试一个人面对名誉受损的韧性，当众问他“你还混得很差吗？”或“你还在亏钱吗？”，然后观察他的反应。', 34);
insert into public.sentences (text, text_zh, notebook_id) values ('Robustness is progress without impatience.', '坚韧是不焦躁的进步。', 34);
insert into public.sentences (text, text_zh, notebook_id) values ('When conflicted between two choices, take neither.', '在两个选择间犹豫时，两者皆不取。', 34);
insert into public.sentences (text, text_zh, notebook_id) values ('Nationstates like war; citystates like commerce; families like stability; and individuals like entertainment.', '民族国家偏好战争；城邦偏好商业；家庭偏好稳定；个人偏好娱乐。', 34);
insert into public.sentences (text, text_zh, notebook_id) values ('Robust is when you care more about the few who like your work than the multitude who dislike it (artists); fragile when you care more about the few who dislike your work than the multitude who like it (politicians).', '坚韧：更在意少数喜欢你作品的人，而非多数不喜欢的人（艺术家）；脆弱：更在意少数不喜欢你作品的人，而非多数喜欢的人（政治家）。', 34);
insert into public.sentences (text, text_zh, notebook_id) values ('The rationalist imagines an imbecilefree society; the empiricist an imbecileproof one, or, even better, a rationalist-proof one.', '理性主义者设想没有蠢人的社会；经验主义者设想对蠢人免疫的社会，甚至更好的是对理性主义者也免疫的社会。', 34);
insert into public.sentences (text, text_zh, notebook_id) values ('Academics are only useful when they try to be useless (say, as in mathematics and philosophy) and dangerous when they try to be useful.', '学者在力求“无用”（如数学与哲学）时才有用；在力求“有用”时反而危险。', 34);
insert into public.sentences (text, text_zh, notebook_id) values ('For the robust, an error is information; for the fragile, an error is an error.', '对坚韧者，错误是信息；对脆弱者，错误只是错误。', 34);
insert into public.sentences (text, text_zh, notebook_id) values ('The best test of robustness to reputational damage is your emotional state (fear, joy, boredom) when you get an email from a journalist.', '检验是否能承受名誉打击的最佳方式，是你收到记者邮件时的情绪状态（恐惧、喜悦或无聊）。', 34);
insert into public.sentences (text, text_zh, notebook_id) values ('The main disadvantage of being a writer, particularly in Britain, is that there is nothing you can do in public or private that would damage your reputation.', '作为作家的主要劣势，尤其是在英国，是无论公开还是私下你几乎做不出会损害名声的事。', 34);
insert into public.sentences (text, text_zh, notebook_id) values ('Passionate hate (by nations and individuals) ends by rotation to another subject of hate; mediocrity cannot handle more than one enemy. This makes warring statelings with shifting alliances and enmities a robust system.', '炽热的仇恨（来自国家或个人）会转移到新的目标；平庸者无法同时对付多个敌人。这使得联盟和仇怨不断变换的小国争霸成为一个稳健的系统。', 34);
insert into public.sentences (text, text_zh, notebook_id) values ('I find it inconsistent (and corrupt) to dislike big government while favoring big businessbut (alas) not the reverse.', '一边厌恶大政府，一边偏爱大企业，我认为这是不一致（且腐败）的；可惜人们却很少反过来想。', 34);
insert into public.sentences (text, text_zh, notebook_id) values ('How often have you arrived one, three, or six hours late on a transatlantic 8ight as opposed to one, three, or six hours early? This explains why deficits tend to be larger, rarely smaller, than planned.', '跨洋航班你有多少次是晚到一、三或六小时，而不是早到一、三或六小时？这解释了为什么赤字往往比计划更大、很少更小。', 34);
